/* BmsMobBwstMapper.insertStockScanInfo : 재고실사 - 재고PKG SCAN 시작종료 생성 */
INSERT INTO TB_BMS_STOCK_SCAN_START_END (
	SCAN_DATE,
	SCAN_START_TIME,
	SCAN_END_TIME,
	CHUTE_STOCK_YN,
	REGISTER_USER_ID,
	REGISTER_DATE_TIME,
	UPDATE_USER_ID,
	UPDATE_DATE_TIME
) VALUES (
	CONVERT(VARCHAR(10),GETDATE(),120)
	, CONVERT(CHAR(8), GETDATE(), 8)
	, ''
	, #{chuteStockYn}
	, #{registerUserId}
	, GETDATE()
	, #{updateUserId}
	, GETDATE()
)

