mapper.update:
/* BmsMobBwstMapper.updateStockScanInfo : 재고실사 - 재고실사 PKG 조회 */ UPDATE TB_BMS_STOCK_SCAN_START_END SET SCAN_END_TIME = CONVERT(CHAR(8), GETDATE(), 8), SCAN_END_DATE = CONVERT(VARCHAR(10),GETDATE(),120)
, STOCK_SCAN_SEQ = #{stockScanSeq}
WHERE
SCAN_END_TIME = ''

mapper.select:
/* BmsMobBwstMapper.selectStockInfo : 재고실사 - 재고PKG SCAN 조회 */ SELECT P.IN_PLAN_NO, P.BL_NO, P.CARGO_REFERENCE_NO, P.OD_JOB_NO, PP.PACKING_NO FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO WHERE PP.PACKING_NO = #{packingNo}
AND PP.SEQ = #{srchSeq}
AND PP.DELETE_YN = 'N'

