mapper.select:
/* BmsMobBwstMapper.checkPkgHasBmsIn : 해당박스가 반입이 생성 됬는지 count */
	SELECT
		COUNT(*)	
	FROM TB_BMS_IN_PLAN_PKG pkg WITH (NOLOCK)
	INNER JOIN TB_BMS_IN i WITH (NOLOCK)
		ON i.IN_PLAN_NO = pkg.IN_PLAN_NO
	WHERE pkg.PACKING_NO = #{packingNo}

			AND pkg.SEQ = #{srchSeq}

/* BmsMobBwstMapper.selectOutPlanInfoByPkgNo : PKG SCAN으로 OUT_PLAN 반출승인 조회 */ SELECT TOP 1 outPlan.APPROVAL_CLASS , outPlan.OUT_CLASS , COALESCE(outPlan.IN_NO, carryIn.IN_NO, 0) AS IN_NO FROM TB_BMS_IN_PLAN_PKG pkg WITH(NOLOCK) LEFT JOIN TB_BMS_IN carryIn WITH(NOLOCK) ON carryIn.IN_PLAN_NO = pkg.IN_PLAN_NO OR carryIn.ORIG_IN_PLAN_NO = pkg.IN_PLAN_NO LEFT JOIN TB_BMS_OUT_PLAN outPlan WITH(NOLOCK) ON outPlan.IN_NO = carryIn.IN_NO WHERE pkg.PACKING_NO = #{packingNo}
AND pkg.SEQ = #{srchSeq}
AND pkg.DELETE_YN = 'N' ORDER BY outPlan.NOTIFY_DATE_TIME DESC

/* BmsMobBwstMapper.selectCurrentStockScanSeq : 현재 재고실사SCAN 차수 가져오기 */ SELECT TOP 1 CASE WHEN A.STOCK_SCAN_SEQ IS NOT NULL THEN A.STOCK_SCAN_SEQ + 1 ELSE 1 END FROM( SELECT TOP 1 SCAN_DATE AS SCAN_DATE_BEFORE, STOCK_SCAN_SEQ, NULL AS SCAN_DATE_CURRENT FROM TB_BMS_STOCK_SCAN_START_END WHERE SCAN_DATE < CONVERT(CHAR(10), GETDATE(), 23) AND STOCK_SCAN_SEQ IS NOT NULL ORDER BY SCAN_DATE DESC
UNION ALL
SELECT TOP 1 NULL AS SCAN_DATE_BEFORE, STOCK_SCAN_SEQ, SCAN_DATE AS SCAN_DATE_CURRENT FROM TB_BMS_STOCK_SCAN_START_END WHERE SCAN_DATE = CONVERT(CHAR(10), GETDATE(), 23) ORDER BY SCAN_DATE DESC, STOCK_SCAN_SEQ DESC ) AS A ORDER BY A.SCAN_DATE_CURRENT DESC, A.STOCK_SCAN_SEQ DESC
